    def generate_cnf(n, m):
        variables = [f'x{i}' for i in range(1, n+1)]
        clauses = []
        for _ in range(m):
            clause = random.sample(variables + [-v for v in variables], 3)
            clauses.append(clause)
        return clauses

    def gram_matrix(cnf):
        n = len(cnf)
        M = [[0] * n for _ in range(n)]
        for i, clause in enumerate(cnf):
            for j, clause2 in enumerate(cnf):
                count = sum(1 for v in clause if -v in clause2)
                M[i][j] = count
        return M

    def smith_normal_form(M):
        n = len(M)
        U = [[0] * n for _ in range(n)]
        V = [[0] * n for _ in range(n)]
        for i in range(n):
            U[i][i] = 1
            V[i][i] = 1

        def pivot(M, r, c):
            M[r], M[c] = M[c], M[r]
            for j in range(c+1, n):
                M[r][j] /= M[r][c]
            for i in range(n):
                if i != r:
                    factor = M[i][c]
                    for j in range(c, n):
                        M[i][j] -= factor * M[r][j]

        def find_pivot(M):
            for i in range(n):
                for j in range(n):
                    if M[i][j] != 0:
                        return i, j
            return None

        while True:
            pivot_row, pivot_col = find_pivot(M)
            if pivot_row is None:
                break
            pivot(M, pivot_row, pivot_col)

        for r in range(n):
            for c in range(r+1, n):
                M[r][c] = 0

        return M

    def resolution_length(cnf):
        stack = cnf[:]
        while True:
